// AND (&&) — both must be true
true && true    // true
true && false   // false

// OR (||) — at least one must be true
true || false   // true
false || false  // false

// NOT (!) — flips true/false
!true   // false
!false  // true

// Short-circuit evaluation
const user = null;
const name = user && user.name;   // null (stops early — user is falsy)
const display = name || 'Guest'; // 'Guest' (fallback when name is falsy)

// Nullish coalescing (??) — only falls back on null/undefined (not 0 or '')
const score = 0;
const display1 = score || 'No score';  // 'No score' (WRONG — 0 is falsy!)
const display2 = score ?? 'No score';  // 0 (CORRECT — 0 is not null/undefined)

const user = { profile: { name: 'Prashant' } };
const guestUser = null;

// Without optional chaining — throws if user is null
const name1 = user.profile.name;       // 'Prashant'
const name2 = guestUser.profile.name;  // TypeError: Cannot read properties of null

// With optional chaining — safely returns undefined
const name3 = guestUser?.profile?.name;  // undefined (no error)
const name4 = guestUser?.profile?.name ?? 'Guest';  // 'Guest'
